}

// src/despachos/despachos.service.ts
const MAX_KG_POR_BULTO = 25; // regla de negocio inventada

@Injectable()
export class DespachosService {
  constructor(private readonly repo: RepositorioDespachos) {}

  crear(datos: { cliente: string; bultos: number; kg: number }) {
    if (datos.kg / datos.bultos > MAX_KG_POR_BULTO) {
      throw new UnprocessableEntityException(`más de ${MAX_KG_POR_BULTO} kg por bulto`);
    }
    return this.repo.crear(datos);
  }
}

