@Injectable()
export class ApiKeyGuard implements CanActivate {
  canActivate(contexto: ExecutionContext): boolean {
    const req = contexto.switchToHttp().getRequest();
    if (req.headers['x-api-key'] !== 'CLAVE-FALSA-DE-PRACTICA') {
      throw new UnauthorizedException('falta la clave o es incorrecta');
    }
    return true;
  }
}

const nuevoDespacho = z.object({
  cliente: z.string().min(2),
  bultos: z.number().int().positive(),
  kg: z.number().positive(),
});

@Controller('despachos')
@UseInterceptors(TiempoInterceptor)
export class DespachosController {
  constructor(private readonly servicio: DespachosService) {}

  @Get(':id')
  obtener(@Param('id', ParseIntPipe) id: number) { return this.servicio.obtener(id); }

  @Post()
  @UseGuards(ApiKeyGuard)
  crear(@Body({ schema: nuevoDespacho }) datos: z.infer<typeof nuevoDespacho>) {
    return this.servicio.crear(datos);
  }
}
